-- Phase 4+5 shared contracts (Wave 0, see docs/PHASE4_5_PLAN.md).
-- Agents add their own migrations in their number range; they do NOT edit this file.

-- ---------------------------------------------------------------- consent withdrawal (B)
alter table public.consents add column if not exists withdrawn_reason text;

-- ---------------------------------------------------------------- offline (E)
alter table public.sessions add column if not exists offline_synced_at timestamptz;

-- ---------------------------------------------------------------- multi-site studies (D)
create table public.studies (
  id             uuid primary key default gen_random_uuid(),
  name           text not null check (length(name) between 1 and 200),
  lead_org_id    uuid not null references public.organizations on delete cascade,
  created_by     uuid references auth.users on delete set null,
  blind_default  boolean not null default false,
  created_at     timestamptz not null default now()
);

create table public.study_sites (
  study_id   uuid not null references public.studies on delete cascade,
  org_id     uuid not null references public.organizations on delete cascade,
  status     text not null default 'invited' check (status in ('invited', 'active', 'left')),
  joined_at  timestamptz,
  primary key (study_id, org_id)
);
create index study_sites_org_idx on public.study_sites (org_id);

-- A session may belong to one study (set by the site that ran it).
alter table public.sessions add column if not exists study_id uuid references public.studies on delete set null;

alter table public.studies enable row level security;
alter table public.study_sites enable row level security;

-- Visible to members of the lead org and of any participating site. Writes go through
-- server routes / RPCs owned by agent D (no insert/update/delete policies here).
-- SECURITY DEFINER helper avoids the studies <-> study_sites policy recursion.
create or replace function public.can_see_study(p_study uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.studies s where s.id = p_study and public.is_member(s.lead_org_id))
      or exists (select 1 from public.study_sites ss where ss.study_id = p_study and ss.status <> 'left' and public.is_member(ss.org_id));
$$;

create policy studies_select on public.studies for select to authenticated using (public.can_see_study(id));
create policy study_sites_select on public.study_sites for select to authenticated using (public.can_see_study(study_id));

-- ---------------------------------------------------------------- areas of interest (C)
create table public.aoi_sets (
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null references public.organizations on delete cascade,
  level       int not null check (level between 1 and 3),
  video_id    text not null,
  name        text not null check (length(name) between 1 and 120),
  -- [{ "label": "face", "x": 0.1, "y": 0.2, "w": 0.3, "h": 0.4, "tStartS": 0, "tEndS": 11 }] in stimulus-area fractions
  boxes       jsonb not null default '[]'::jsonb,
  created_by  uuid references auth.users on delete set null,
  created_at  timestamptz not null default now()
);
alter table public.aoi_sets enable row level security;
create policy aoi_select on public.aoi_sets for select to authenticated using (public.is_member(org_id));
create policy aoi_insert on public.aoi_sets for insert to authenticated with check (public.has_role(org_id, '{admin,staff}'));
create policy aoi_update on public.aoi_sets for update to authenticated
  using (public.has_role(org_id, '{admin,staff}')) with check (public.has_role(org_id, '{admin,staff}'));
create policy aoi_delete on public.aoi_sets for delete to authenticated using (public.has_role(org_id, '{admin,staff}'));

-- Keep AOI sets in their organization.
create or replace function public.aoi_keep_org() returns trigger language plpgsql as $$
begin
  if new.org_id is distinct from old.org_id then raise exception 'org_change_not_allowed'; end if;
  return new;
end $$;
create trigger aoi_keep_org before update on public.aoi_sets for each row execute function public.aoi_keep_org();

-- ---------------------------------------------------------------- audit actions used by Phase 4+5 pages
create or replace function public.log_action(p_org uuid, p_action text, p_target text default null)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_member(p_org) then raise exception 'not_allowed'; end if;
  if p_action not in (
    'view_session', 'export_sessions_csv', 'export_gaze_csv',
    'view_stats', 'export_stats_csv', 'export_analysis_csv',
    'view_study_summary', 'export_study_csv'
  ) then
    raise exception 'bad_action';
  end if;
  insert into public.audit_log (org_id, user_id, action, target) values (p_org, auth.uid(), left(p_action, 60), left(p_target, 200));
end $$;
